import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
V=np.var(y)
def T(c,p,q,r,kind):
    if kind==0: return c*t**p*A**q*np.exp(-r*A)
    if kind==1: return c*t**p*A**q*np.exp(-r*t)
    if kind==2: return c*t**p*A**q*np.exp(-r*A*t)
    if kind==3: return c*t**p*A**q*np.log(A+abs(r))
    if kind==4: return c*t**p*(A**q)/(1+abs(r)*A)
def run(kinds,ntry=30):
    n=len(kinds)
    def f(x):
        out=0
        for i,k in enumerate(kinds):
            c,p,q,r=x[4*i:4*i+4]
            out=out+T(c,p,q,r,k)
        return out
    best=None; rng=np.random.default_rng(1)
    for _ in range(ntry):
        x0=[]
        for i in range(n):
            x0+= [rng.normal(), rng.uniform(0,2), rng.uniform(-1,3), rng.uniform(0,2)]
        try:
            with np.errstate(all='ignore'):
                r=least_squares(lambda x: np.nan_to_num(f(x)-y,nan=1e3,posinf=1e3,neginf=-1e3), x0, max_nfev=2000)
            v=np.mean(r.fun**2)/V
            if best is None or v<best[0]: best=(v,np.round(r.x,3))
        except Exception as e: pass
    return best
for kinds in [[0,0],[0,1],[0,2],[1,1],[0,3],[3,0],[0,4],[2,2],[0,0,0]]:
    print(kinds, run(kinds,20))
